  "„Alle erinnern“ in den Beiträgen wartet so viele Tage nach der Fälligkeit und kann einen Zusatztext anhängen.": "«Нагадати всім» у розділі внесків чекає стільки днів після строку сплати й може додати додатковий текст.",
  "„Anlage & Material“ ist im Verein nicht aktiviert.": "«Майно й матеріали» не активовано в клубі.",
  "„Automatisch zugesagt“ ist empfohlen; bei aktiver Antwort gilt jede Person als offen, bis sie antwortet. Änderungen gelten für neue Termine.": "Рекомендовано «Автоматично підтверджено»; за активної відповіді кожен вважається невизначеним, доки не відповість. Зміни діють для нових заходів.",
  "„Fällige Beiträge anlegen“ erzeugt für alle zugeordneten Mitglieder die Forderungen, die bis heute fällig sind – nie doppelt.": "«Створити належні внески» формує для всіх призначених членів клубу вимоги, строк сплати яких настав до сьогодні – ніколи двічі.",
  "„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.": "«Я → Налаштування → Запросити» або в команді «Запросити особу до команди»: особисто електронною поштою або як посилання чи QR-код команди для самореєстрації. У разі посилань ти схвалюєш нові запити, перш ніж хтось зможе користуватися застосунком.",
  "„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.": "«Редагувати команду → Імпортувати календар матчів»: вибери CSV-файл із DFBnet, перевір попередній перегляд (нові, змінені, без змін, пропущені) і застосуй. Команда отримає одне загальне повідомлення. Повторний імпорт оновлює перенесення замість дублювання матчів. Протягом 24 годин імпорт можна скасувати.",
  "„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.": "«Команда → Склад → Редагувати команду»: додавай гравців зі списку клубу або виключай зі складу, змінюй роль (гравець, асистент тренера, наглядач) і номер на футболці, призначай скарбника. Внизу ти налаштовуєш, за скільки хвилин до матчів і тренувань ви збираєтеся, стандартне місце збору та написання назви вашої команди в DFBnet. Асистенти тренера мають ті самі права, що й тренер.",
  "„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.": "«Команда → Каса → Керування касою». Там розміщені плитки: надходження/витрата, внески, призначити штраф, список напоїв, розкладка витрат, членські внески, проводки й сторно, скарбник, платіжна інформація та касова перевірка.",
  "„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.": "«Команда → Створити подію»: тренування, матч або командна подія. Матчі отримують тип: ліга, кубок або товариський матч. Для повторення вибери «Щотижня до …» і дату завершення (до приблизно одного року). Час збору застосунок розраховує за правилами твоєї команди; в окремій події його можна змінити. У події через «Редагувати подію» ти змінюєш окремі події або «цю й наступні». Після «Скасувати подію» команда одразу отримує сповіщення.",
  "„Unsicher“ als Antwort erlauben": "Дозволити відповідь «Не впевнений»",
