  "Artikel pflegt die Vereinsverwaltung.": "Статті веде адміністрація клубу.",
  "Artikel schreiben": "Написати статтю",
  "Auch Dubletten werden als neue Einträge angelegt.": "Дублікати теж буде створено як нові записи.",
  "auch mehrere auf einmal": "також кілька одразу",
  "Auch Mitspieler sehen den Grund einer Absage oder Abwesenheit (z. B. verletzt, krank).": "Партнери по команді також бачать причину відмови чи відсутності (напр., травма, хвороба).",
  "Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.": "Навіть без реклами спонсор залишається видимим в огляді.",
  "Audit-Log einsehen": "Переглядати журнал аудиту",
  "Auf der letzten Seite findest du die passenden Schaltflächen.": "На останній сторінці ти знайдеш відповідні кнопки.",
  "Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.": "На головній сторінці та в «Клуб → Новини». Термінові повідомлення стоять угорі й надходять також через push. Реагувати можна через «Подобається» та коментарі.",
  "Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.": "За цією вимогою вже сплачено. Спершу сторнуй проводку в касовій книзі.",
  "Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.": "На кожній підсторінці вгорі видно твій шлях, наприклад «Команда › Каса › Каталог штрафів». Торкнись попереднього рівня, щоб повернутися до нього, або круглої стрілки, щоб повернутися на крок назад. У довгих шляхах «…» замінює пропущені рівні; дотик показує їх списком. Нижня панель залишається видимою, поточний розділ позначено.",
  "Auf Konto": "На рахунок",
  "auf später verschoben": "відкладено на потім",
  "Auf Start und unter Termine sagst du zu oder ab. Mit „Rückgängig“ nimmst du es gleich wieder zurück.": "На головній і в розділі «Події» ти підтверджуєш або відмовляєшся. Через «Скасувати дію» одразу можна це відкликати.",
