  "Aus Datei übernehmen": "Імпортувати з файлу",
  "Aus Datenschutzgründen siehst du nur Zahlen. Den Trainer der Mannschaft kannst du über „Ansprechpartner“ erreichen.": "З міркувань захисту даних ти бачиш лише цифри. Тренера команди можна знайти через «Контактна особа».",
  "Aus dem DFBnet oder als Tabelle": "З DFBnet або як таблиця",
  "Aus dem Kader nehmen": "Виключити зі складу",
  "Aus dem Strafenkatalog": "З каталогу штрафів",
  "Aus diesen Regeln berechnet die App bei jedem neuen Spiel und Training die Treffzeit. Beim einzelnen Termin kannst du sie jederzeit überschreiben. Leer lassen = kein automatisches Treffen.": "За цими правилами застосунок розраховує час збору для кожного нового матчу й тренування. В окремій події його можна змінити будь-коли. Залишити порожнім = без автоматичного збору.",
  "Aus einer Excel- oder CSV-Datei. Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung.": "З файлу Excel або CSV. Спершу ти побачиш попередній перегляд – імпорт відбудеться лише після твого підтвердження.",
  "Aus Excel oder CSV, mit Vorlage zum Herunterladen": "З Excel або CSV, із шаблоном для завантаження",
  "Aus Excel oder CSV; DFBnet-Dateien gehen über „Spielplan importieren“": "З Excel або CSV; файли DFBnet імпортуються через «Імпортувати календар матчів»",
  "Aus Vereinsliste": "Зі списку клубу",
  "Aus: Jede Person sieht nur die eigenen Beträge. Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft.": "Вимк.: кожен бачить лише власні суми. Стан каси, надходження й витрати завжди бачить уся команда.",
  "Ausblenden": "Приховати",
