  "ausgegeben {0}": "видано {0}",
  "Ausgeglichen": "Збалансовано",
  "Ausgeschaltete Module verschwinden aus der App; Daten bleiben erhalten. Mannschaftsmodule lassen sich zusätzlich je Mannschaft einstellen (Verwaltung → Mannschaften).": "Вимкнені модулі зникають із застосунку; дані зберігаються. Командні модулі можна додатково налаштувати для кожної команди (Адміністрування → Команди).",
