  "Beginn im {0}": "Початок у {0}",
  "Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.": "Починається {0}. Склади плануються в Адміністрування → Члени клубу: команди нового сезону там позначені «(сезон {1})».",
  "Begründung": "Обґрунтування",
  "Begründung (bei Ablehnung)": "Обґрунтування (у разі відхилення)",
  "Begründung für das Storno": "Причина сторно",
  "Begünstigter Zweck": "Пільгова мета",
  "Bei „Nur der Kassenwart“ dürfen Trainer ohne Kassenwart-Aufgabe nichts mehr buchen und keine Strafen vergeben; sie sehen die Kasse weiterhin.": "За варіанта «Лише касир» тренери без завдання касира більше не можуть вносити записи й виписувати штрафи; касу вони все ще бачать.",
  "Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.": "Для виїзних матчів і турнірів у події є розділ «Спільні поїздки». Торкнись «Я їду» та вкажи вільні місця або вибери в авто «Поїхати разом». Хто не має, з ким поїхати, торкається «Шукати попутників». Батьки бронюють для своїх дітей.",
  "Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.": "Під час входу ми надсилаємо тобі 6-значний код електронною поштою (діє 10 хвилин, лише один раз). Безпечніше — застосунок-автентифікатор, а код з електронної пошти — простіша альтернатива.",
  "Bei dir": "У тебе",
  "Bei Dubletten": "У разі дублікатів",
  "Bei einer Absage ist ein Grund Pflicht": "Для відмови причина обов’язкова",
  "Bei Spielen fehlt der Gegner.": "Для матчів не вказано суперника.",
  "bei Spielen Pflicht": "для матчів обов’язково",
  "Bei Terminen fehlt der Titel.": "Для подій не вказано назву.",
  "bei Terminen Pflicht, sonst automatisch": "для подій обов’язково, інакше автоматично",
  "Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.": "У подіях ти бачиш відповідь кожної особи. Підтвердження й відмови діють для кожної дитини окремо.",
  "Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.": "На клубних заходах (напр., загальні збори, турнір) ти можеш обрати «Підтвердити», «Відмовитися» або «Не впевнений» – без обґрунтування. Часто є також «Потрібні помічники»: запишись на зміну.",
  "beidfüßig": "обома ногами",
  "Beidfüßig": "Обома ногами",
  "Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.": "Під час вибуття всі призначення до команд завершуються, ролі скасовуються, а доступ до застосунку блокується. Дані зберігаються для документації клубу.",
  "Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).": "Під час запису надходження ти вибираєш спонсора (Клуб → Спонсори).",
  "Beim Eigentor des Gegners gibt es keinen Torschützen.": "Для автогола суперника автора голу немає.",
  "Beim Kassenwart oder Trainerteam": "У скарбника або тренерського штабу",
  "Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.": "Під час видалення автоматичні відмови скасовуються. У команд з активним підтвердженням/відмовою відповідь після цього знову відкрита.",
  "Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.": "Під час планування заходу вгорі вибери групу («Весь клуб», одне відділення …). Через «Вибрати команди або осіб» ти запрошуєш цілеспрямовано: познач у вікні команди галочками або знайди осіб. Вибір з’являється у вигляді чипів; через «×» когось можна прибрати. Сповіщення отримують лише запрошені. Окремих осіб можна запрошувати лише з правом на список членів клубу.",
  "Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.": "Під час запуску й після хвилини у фоновому режимі застосунок запитує Face ID, відбиток пальця або код пристрою. Налаштування діє лише на цьому пристрої.",
  "Beispiel": "Приклад",
