  "Beispieltext: Die Haftung richtet sich nach den gesetzlichen Vorschriften. Details folgen in der endgültigen Fassung.": "Приклад тексту: відповідальність визначається законодавчими приписами. Подробиці будуть у остаточній редакції.",
