  "Beitragsforderungen, die noch offen sind (etwa aus einer alten Liste). Das Mitglied braucht dafür die Beitragszuordnung.": "Вимоги щодо внесків, які ще відкриті (наприклад, зі старого списку). Для цього член клубу потребує призначення внеску.",
