  "Bereinigen?": "Очистити?",
  "Bereite die nächste Saison vor: Alle Mannschaften werden mit Modulen, Fristen, Trainerteams und Zusatzaufgaben (z. B. Kassenwart) übernommen. Die laufende Saison bleibt unverändert, bis du die neue startest.": "Підготуй наступний сезон: усі команди буде перенесено з модулями, строками, тренерськими штабами та додатковими обов’язками (напр., скарбник). Поточний сезон залишається без змін, доки ти не запустиш новий.",
  "Bereits eingegangen": "Уже надійшло",
