  "Beschreibe das Ergebnis der Prüfung. Danach ist der Bericht abgegeben und nicht mehr änderbar; er ist die Grundlage der Entlastung.": "Опиши результат перевірки. Після цього звіт буде подано, і його більше не можна змінити; він є підставою для розвантаження (затвердження звітності).",
