  "Buchungen werden nie gelöscht, sondern storniert: „Buchungen & Storno“, Buchung antippen, optional Grund eintragen. Die Buchung bleibt durchgestrichen sichtbar und steht im Änderungsprotokoll. Zum Korrigieren neu buchen.": "Проводки ніколи не видаляються, а сторнуються: «Проводки й сторно», торкнись проводки, за бажанням вкажи причину. Проводка залишається видимою закресленою та потрапляє до журналу змін. Щоб виправити, створи нову проводку.",
