  "Daten werden gelöscht, wenn sie nicht mehr gebraucht werden oder du es verlangst, sofern keine gesetzliche Aufbewahrungspflicht besteht.": "Дані видаляються, коли вони більше не потрібні або коли ти цього вимагаєш, якщо немає законного обов’язку зберігання.",
  "Daten, Foto und Auswertung": "Дані, фото й звіт",
