  "Datenschutzerklärung": "Політика конфіденційності",
  "Datenschutzerklärung und Impressum findest du in der App unter Ich › Hilfe und Informationen.": "Політику конфіденційності та імпресум ти знайдеш у застосунку в Я › Довідка та інформація.",
  "Datensparsam voreingestellt: Gründe und Beteiligung sieht nur das Trainerteam.": "За замовчуванням — мінімум даних: причини та участь бачить лише тренерський штаб.",
  "Datenübergabe und Leeren": "Передача даних і очищення",
