  "Davon hängt ab, welche Bereiche (ideeller Bereich, Zweckbetrieb, wirtschaftlicher Geschäftsbetrieb) die Kasse unterscheidet.": "Від цього залежить, які сфери (ідеальна сфера, цільова діяльність, господарська діяльність) розрізняє каса.",
  "davon überfällig {0}": "з них прострочено {0}",
