  "Dein Code zur Einrichtung deines Vereins in Clubroof lautet: {0}\n\nEr ist 15 Minuten gültig. Wenn du die Einrichtung nicht gestartet hast, ignoriere diese E-Mail.": "Твій код для налаштування клубу в Clubroof: {0}\n\nВін діє 15 хвилин. Якщо ти не запускав(ла) налаштування, проігноруй цей лист.",
