  "Deine Rückmeldung wird gesendet, sobald du wieder online bist.": "Твою відповідь буде надіслано, щойно ти знову будеш онлайн.",
  "Deine Schadensmeldung ist {0}": "Твоє повідомлення про пошкодження: {0}",
  "Deine Termine (und die deiner Kinder) sowie die Vereinstermine erscheinen automatisch in deinem Kalender – Änderungen und Absagen inklusive. Teilnehmerlisten werden nicht übertragen.": "Твої події (та події твоїх дітей) і події клубу автоматично з’являються в твоєму календарі – зі змінами й скасуваннями. Списки учасників не передаються.",
  "Deine Trainerin oder dein Trainer und die Ansprechpartner des Vereins helfen dir gern weiter.": "Твій тренер або тренерка та контактні особи клубу охоче допоможуть.",
