  "Dem Mitglied ist diese Beitragsart nicht zugeordnet (zuerst die Zuordnung importieren).": "Цьому члену клубу цей вид внеску не призначено (спершу імпортуй призначення).",
  "Demoverein": "Демоклуб",
  "Den eigenen Austritt trägt eine andere Person ein.": "Власне вибуття вносить інша особа.",
  "Den Einrichtungscode bekommst du von Clubroof, sobald die Zahlung eingegangen ist. Er gilt einmal.": "Код налаштування ти отримаєш від Clubroof, щойно надійде оплата. Він дійсний один раз.",
  "Den Gesamtexport darf nur die Administration.": "Загальний експорт може робити лише адміністрація.",
  "Den Import macht nur die Person rückgängig, die ihn durchgeführt hat.": "Імпорт скасовує лише та особа, яка його виконала.",
  "Den Kader bearbeitet nur das Trainerteam der Mannschaft.": "Склад редагує лише тренерський штаб команди.",
  "Den Kassenbericht sieht die Mannschaft.": "Касовий звіт бачить команда.",
