  "Den Spielplan importieren nur Trainerteam und Vereinsverwaltung.": "Календар матчів імпортують лише тренерський штаб і адміністрація клубу.",
  "Den Strafenkatalog pflegen Trainerteam und Kassenwart.": "Каталог штрафів ведуть тренерський штаб і скарбник.",
