  "Der Code ist abgelaufen. Bitte fordere einen neuen an.": "Строк дії коду минув. Запроси новий.",
  "Der Code ist unterwegs.": "Код уже в дорозі.",
  "Der Code konnte nicht geprüft werden.": "Код не вдалося перевірити.",
