  "Der Code per E-Mail ist nicht eingerichtet.": "Код електронною поштою не налаштовано.",
  "Der Code stimmt nicht oder ist abgelaufen.": "Код невірний або строк його дії минув.",
  "Der Code stimmt nicht.": "Код невірний.",
  "Der Code stimmt nicht. Bitte den aktuellen Code eingeben.": "Код невірний. Введи актуальний код.",
  "Der Eingang wird mit der Buchung erfasst.": "Надходження фіксується разом із проводкою.",
  "Der Einrichtungscode konnte nicht geprüft werden.": "Код налаштування не вдалося перевірити.",
  "Der Einrichtungscode stimmt nicht.": "Код налаштування невірний.",
  "Der Einsatz": "Залучення",
  "Der Export des Archivs steht in der Web-Verwaltung bereit.": "Експорт архіву доступний у веб-адмініструванні.",
  "Der Export hat nicht geklappt.": "Експорт не вдався.",
