  "Einnahmen & Ausgaben": "Надходження й витрати",
  "Einnahmen und Ausgaben": "Надходження й витрати",
  "Einnahmen und Ausgaben des Kassenbuchs. Der Betrag trägt das Vorzeichen (Ausgaben negativ) oder die Spalte Art sagt „Einnahme“ bzw. „Ausgabe“. Gesperrte Jahre werden abgelehnt.": "Надходження й витрати касової книги. Сума має знак (витрати від’ємні), або стовпець «Вид» містить «Надходження» чи «Витрата». Заблоковані роки відхиляються.",
