  "Einzahlung": "Внесок",
  "Einzahlung buchen": "Записати внесок",
  "Einzahlung Mannschaftskasse": "Внесок до каси команди",
  "Einzahlungen": "Внески",
  "Einzahlungsweg": "Спосіб оплати",
  "Einzeln unter „Mitglieder → Mitglied anlegen“ oder per Import aus Excel oder CSV („Importieren“): Bereich wählen, Vorlage laden, Datei hochladen, Spalten zuordnen, Vorschau prüfen (neu, aktualisiert, Dublette, Fehler), bei Dubletten überspringen, aktualisieren oder neu anlegen. Der Import wird ganz oder gar nicht übernommen und lässt sich 24 Stunden lang rückgängig machen. Austritte beenden Mannschaftszugehörigkeiten und sperren den App-Zugang. In der Mitgliederliste filterst du nach Rolle, Trainerteam, individuellen Rechten oder fehlendem App-Zugang.": "Окремо через «Члени клубу → Створити члена клубу» або імпортом з Excel чи CSV («Імпортувати»): вибери розділ, завантаж шаблон, завантаж файл, зістав стовпці, перевір попередній перегляд (нові, оновлені, дублікати, помилки), у разі дублікатів пропусти, оновити або створити нових. Імпорт застосовується повністю або не застосовується взагалі й може бути скасований протягом 24 годин. Вибуття завершує належність до команд і блокує доступ до застосунку. У списку членів клубу можна фільтрувати за роллю, тренерським штабом, індивідуальними правами або відсутністю доступу до застосунку.",
  "Einzelne Personen einladen dürfen nur Berechtigte.": "Запрошувати окремих осіб можуть лише уповноважені.",
  "Einzelne Rechte zusätzlich zu den Rollen vergeben": "Надавати окремі права додатково до ролей",
  "Einzelne Spiele unter Termine anlegen": "Створювати окремі матчі в розділі «Події»",
