  "Eltern und Spieler treten mit einem Link bei und werden von dir freigegeben.": "Батьки й гравці вступають за посиланням, а ти їх схвалюєш.",
  "Eltern, die mit ihrem Kind verknüpft sind, antworten für das Kind und sehen dessen Termine. Ohne Verknüpfung sagt niemand für das Kind zu.": "Батьки, пов’язані зі своєю дитиною, відповідають за дитину та бачать її заходи. Без зв’язку за дитину ніхто не відповідає.",
