  "Empfohlene Reihenfolge: zuerst die Mitglieder, dann Mannschaften und Kader, zuletzt Termine und Kasse – so findet jeder Import seine Personen und Mannschaften wieder.": "Рекомендований порядок: спершу члени клубу, потім команди й склади, наприкінці події та каса – так кожен імпорт знайде свої особи й команди.",
