  "Endgültig löschen?": "Видалити назавжди?",
  "Engagiert im Verein ohne Amt oder Mannschaft: Vereinsüberblick, Veranstaltungen, News verfassen (zur Freigabe), keine Verwaltungsrechte": "Активна участь у клубі без посади чи команди: огляд клубу, заходи, написання новин (на схвалення), без прав адміністрування",
