  "Erinnert wird nur zu überfälligen Forderungen.": "Нагадування надсилаються лише щодо прострочених вимог.",
  "Erinnerung": "Нагадування",
  "Erinnerung Stufe {0} senden": "Надіслати нагадування рівня {0}",
  "Erinnerung vor der Frist": "Нагадування перед строком",
  "Erinnerung vor der Frist (Stunden, 0 = keine)": "Нагадування перед строком (години, 0 = без нагадування)",
  "Erinnerung, Bezahlinfos und Kassenprüfung?": "Нагадування, платіжна інформація та касова перевірка?",
  "Erinnerungen": "Нагадування",
  "Erinnerungen an offene Beträge verschickst du per Knopf oder lässt sie monatlich automatisch laufen (Einstellungen). Unter „Bezahlinfos & Einstellungen“ hinterlegst du IBAN und PayPal und bestimmst, ob alle die Beträge aller Beteiligten sehen (Standard: jeder nur die eigenen; Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft). „Kassenprüfung“ hält den Stand mit Prüfer fest. Berichte gibt es als Excel und PDF.": "Нагадування про несплачені суми ти надсилаєш кнопкою або дозволяєш їм працювати щомісяця автоматично (налаштування). У «Платіжна інформація й налаштування» ти вказуєш IBAN і PayPal та визначаєш, чи бачать усі суми всіх учасників (за замовчуванням кожен бачить лише свої; стан каси, надходження й витрати завжди бачить уся команда). «Касова перевірка» фіксує стан разом із ревізором. Звіти доступні як Excel і PDF.",
  "Erklärung": "Пояснення",
  "Erlaubt sind PDF, Word (.docx), Excel (.xlsx), JPG und PNG.": "Дозволені PDF, Word (.docx), Excel (.xlsx), JPG і PNG.",
  "Erläuterung (optional)": "Коментар (необов’язково)",
  "Erledigen kann, wer den Aushang erstellt hat.": "Позначити виконаним може той, хто створив оголошення.",
  "Erledigt": "Виконано",
