  "Eröffnen": "Відкрити",
  "Erscheint als Zielbalken in der Kassenstatistik. Leer lassen, wenn es kein Ziel gibt.": "Відображається як цільова смуга в статистиці каси. Залиш порожнім, якщо мети немає.",
  "Erscheint in der Übersicht": "Відображається в огляді",
