  "Erwachsene": "Дорослі",
  "Erwartete Zuschüsse": "Очікувані дотації",
  "Es erscheint oben in der App bei allen Mitgliedern. Ohne Logo zeigt die App ein Wappen mit dem Kürzel.": "Він відображається вгорі застосунку в усіх членів клубу. Без логотипу застосунок показує герб зі скороченням.",
  "Es fehlen {0} aktive Schiedsrichter": "Бракує активних суддів: {0}",
  "Es fehlen zugeordnete Pflichtfelder.": "Бракує зіставлених обов’язкових полів.",
  "Es gab nichts zu übernehmen.": "Нічого було застосовувати.",
  "Es gibt {0} neue Funktionen": "Нових функцій: {0}",
  "Es gibt 1 neue Funktion": "Є 1 нова функція",
  "Es gibt bereits Kategorien.": "Категорії вже існують.",
  "Es gibt keine Einnahmekategorie für Beiträge. Lege sie in der Vereinskasse an.": "Немає категорії надходжень для внесків. Створи її в касі клубу.",
  "Es gibt keine neuen Mitglieder zu übernehmen.": "Немає нових членів клубу для імпорту.",
  "Es gibt nichts zu übernehmen.": "Немає чого застосовувати.",
  "Es gibt noch fehlerhafte Zeilen. Bitte korrigieren oder abwählen.": "Ще є рядки з помилками. Виправ їх або зніми вибір.",
  "Es gibt noch keine Erwachsenen mit Login in der Mannschaft.": "У команді ще немає дорослих із логіном.",
  "Es gibt noch keine Kategorien für diese Art. Lege sie unter „Einrichtung“ an.": "Для цього виду ще немає категорій. Створи їх у розділі «Налаштування».",
  "Es gibt nur einen Fulladmin – lege einen zweiten an.": "Є лише один повний адміністратор – створи другого.",
  "Es gibt zwei Wege: Unter „Ich“ stehen direkt unter deinem Profil die zwei farbigen Knöpfe „Admin-Verwaltung“ (violett) und „Vereinskasse“ (blau) – nur die, für die du Rechte hast. Außerdem steht unter „Verein“ in der Gruppe „Meine Vereinsaufgaben“ der Zugang zur „Verwaltung“ (für alle mit Verwaltungsrechten) und zur „Vereinskasse“ (für alle mit Kassenzugriff); am Desktop stehen beide dauerhaft in der Seitenleiste. Beide öffnen einen eigenen Bereich mit farbigem Kopfband und „Zur App“ oben sowie einer Leiste mit Reitern unten. Die Verwaltung hat die Reiter Übersicht, Mitglieder, Sport, Inhalte und Verein – du siehst nur, wofür du Rechte hast. In der Vereinskasse gibt es Übersicht, Buchung, Beiträge, Planung und Auswertung. Funktionen mit „Bald verfügbar“ folgen in einem späteren Update.": "Є два шляхи: у розділі «Я» просто під твоїм профілем є дві кольорові кнопки «Адміністрування» (фіолетова) і «Каса клубу» (синя) – лише ті, на які в тебе є права. Також у розділі «Клуб» у групі «Мої клубні завдання» є доступ до «Адміністрування» (для всіх із правами адміністрування) і до «Каси клубу» (для всіх із доступом до каси); на комп’ютері обидва постійно знаходяться на бічній панелі. Обидва відкривають окремий розділ із кольоровою шапкою та кнопкою «До застосунку» вгорі й панеллю вкладок внизу. Адміністрування має вкладки «Огляд», «Члени клубу», «Спорт», «Вміст» і «Клуб» – ти бачиш лише те, на що маєш права. У касі клубу є «Огляд», «Проводка», «Внески», «Планування» та «Звіти». Функції з позначкою «Скоро буде доступно» з’являться в пізнішому оновленні.",
  "Es ist ein unerwarteter Fehler aufgetreten.": "Сталася неочікувана помилка.",
  "Es ist keine laufende Saison eingerichtet.": "Поточний сезон не налаштовано.",
  "Es muss immer eine Hauptkasse geben. Lege eine andere Kasse als Hauptkasse fest.": "Головна каса має існувати завжди. Призначи головною іншу касу.",
  "Es sind noch {0} Stichproben offen.": "Ще відкритих вибіркових перевірок: {0}.",
  "Es sind noch {0} Stichproben offen. Bitte alle abhaken oder beanstanden.": "Ще відкритих вибіркових перевірок: {0}. Познач їх усі виконаними або висунь зауваження.",
  "Es sind nur noch {0} offen. Zu viel Gezahltes bitte als eigene Einnahme buchen.": "Відкрито лише {0}. Надміру сплачене запиши як окреме надходження.",
  "Es sind schon {0} Spieler nominiert, die Anzahl kann nicht darunter sinken.": "Уже номіновано гравців: {0}, кількість не може бути меншою.",
