  "Feste Gruppen müssen nicht ständig antworten – „Automatisch zugesagt“ spart Nachfragen und zeigt trotzdem, wer fehlt.": "Постійним групам не потрібно постійно відповідати – «Підтверджено автоматично» економить запитання й усе одно показує, кого немає.",
  "Feste Gruppen müssen nicht ständig antworten – „Automatisch zugesagt“ spart Nachfragen und zeigt trotzdem, wer fehlt. Bei Spielen ist die aktive Antwort oft sinnvoller, weil der Kader begrenzt ist.": "Постійним групам не потрібно постійно відповідати – «Автоматично підтверджено» зменшує кількість нагадувань і все одно показує, кого немає. Для матчів активна відповідь часто доцільніша, бо склад обмежений.",
