  "Für die Abteilung sind noch Rollen vergeben (z. B. Jugendleitung).": "Для відділення ще призначені ролі (напр., керівництво молоддю).",
  "Für die Daten deines Vereins ist der Verein verantwortlich, Clubroof verarbeitet sie in seinem Auftrag. Genaue Angaben folgen in der endgültigen Fassung.": "За дані твого клубу відповідає клуб, Clubroof обробляє їх за його дорученням. Точні відомості будуть у остаточній редакції.",
  "Für die Funktion fehlt die Mannschaft.": "Для ролі не вказано команду.",
  "Für die Regeln „jünger als … Jahre“ braucht Clubroof die Geburtsdaten der Mitglieder.": "Для правил «молодше за … років» Clubroof потрібні дати народження учасників.",
  "für die Route": "для маршруту",
