  "Für wen?": "Для кого?",
  "Für Zuwendungsbestätigungen braucht der Verein Angaben aus dem Freistellungsbescheid. Das trägt die Vereinsadministration ein; die Vorlage wird erst nach rechtlicher Prüfung freigegeben.": "Для підтверджень внесків клубу потрібні дані з рішення про звільнення від податків. Їх вносить адміністрація клубу; шаблон схвалюється лише після юридичної перевірки.",
  "Fuß: {0}": "Нога: {0}",
  "Ganz unten auf Start findest du den Schnellzugriff – Abkürzungen zu Seiten, die du oft brauchst. Tippe auf „Hinzufügen“, wähle die Einträge aus und speichere. „Zurücksetzen“ stellt die Voreinstellung für deine Rolle wieder her. Die Auswahl gilt auf allen deinen Geräten.": "Внизу на головній сторінці ти знайдеш швидкий доступ – скорочення до сторінок, які тобі часто потрібні. Торкнись «Додати», вибери записи й збережи. «Скинути» відновлює стандартні налаштування для твоєї ролі. Вибір діє на всіх твоїх пристроях.",
