  "Gehört das Geld dem Verein, muss es in dessen Büchern auftauchen. Klärt das bitte mit dem Kassenwart des Vereins.": "Якщо гроші належать клубу, вони мають бути у його обліку. Уточніть це з касиром клубу.",
