  "Gelöschte Rollen": "Видалені ролі",
  "Gelöschte Rollen lassen sich wiederherstellen.": "Видалені ролі можна відновити.",
  "Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.": "Видалені статті знань, вправи, завдання, спонсори, документи та списані матеріали потрапляють до архіву; у документів файл зберігається, доки архів не очищено. Тренерський штаб відкриває архів своєї команди в «Команда → Архів» (видалені завдання й документи, відновлення). Адміністрація відкриває весь архів у «Адміністрування → Підписка й контроль → Архів»: там ти відновлюєш запис через «Відновити». Якщо його назва вже зайнята, застосунок запитає нову назву. Назавжди видаляється ніколи не автоматично: «Очистити» вилучає те, що старіше за стандартний строк (наразі 2 роки), «Очистити архів» видаляє все; обидві дії лише з твоєї ініціативи та з підтвердженням. «Експортувати архів» зберігає всі архівні записи як файл.",
  "Gemeinnützig": "Неприбутковий",
  "Gemeinnützige Vereine müssen Einnahmen und Ausgaben steuerlich trennen. Ist der Verein nicht gemeinnützig, reicht eine einfachere Kategorieliste.": "Неприбуткові клуби мають розділяти надходження й витрати для податкових цілей. Якщо клуб не неприбутковий, достатньо простішого списку категорій.",
