  "Gib den 6-stelligen Code aus deiner Authenticator-App ein – oder einen deiner Wiederherstellungscodes.": "Введи 6-значний код зі свого застосунку-автентифікатора – або один зі своїх кодів відновлення.",
  "Gib den Einladungscode ein oder füge den Link aus deiner Einladung ein. Du bekommst ihn von deinem Verein per E-Mail, Nachricht oder als QR-Code.": "Введи код запрошення або встав посилання із запрошення. Ти отримуєш його від свого клубу електронною поштою, повідомленням або як QR-код.",
