  "Habt ihr ein Logo?": "У вас є логотип?",
  "Hake nach dem Termin ab, wer wirklich da war. Bis dahin zählen die Zusagen.": "Після події познач, хто справді був. До цього враховуються підтвердження.",
  "Hallo {0},": "Привіт, {0},",
  "Hallo {0},\n\ndeine Anfrage für {1} wurde freigegeben. Du kannst dich jetzt in der App anmelden:\n\n{2}": "Привіт, {0},\n\nтвій запит для {1} схвалено. Тепер ти можеш увійти в застосунок:\n\n{2}",
  "Hallo {0},\n\ndeine Anfrage für {1} wurde leider nicht freigegeben.{2}": "Привіт, {0},\n\nна жаль, твій запит для {1} не схвалено.{2}",
  "Hallo, {0}": "Привіт, {0}",
  "Hallo, Maximilian-Alexander von Hohenzollern-Sigmaringen": "Привіт, Maximilian-Alexander von Hohenzollern-Sigmaringen",
  "Hallo! Wir nutzen Clubroof für {0}: Termine, Zu- und Absagen und alle Infos an einem Ort. Hier kommst du in die Mannschaft: {1}": "Привіт! Ми користуємося Clubroof для {0}: події, підтвердження й відмови та вся інформація в одному місці. Тут ти потрапиш до команди: {1}",
  "Hält den Kassenstand von heute fest – z. B. nach der Kassenprüfung oder zum Saisonende. Der Abschluss erscheint auch im Kassenbericht. Beim Saisonwechsel geht die Kasse automatisch auf die neue Mannschaft über.": "Фіксує стан каси на сьогодні – напр., після касової перевірки або наприкінці сезону. Завершення також відображається в касовому звіті. Під час зміни сезону каса автоматично переходить до нової команди.",
  "Halte die Kamera auf den QR-Code deiner Einladung.": "Наведи камеру на QR-код свого запрошення.",
  "Hartplatz": "Тверде покриття",
  "Hat eine Abteilung eigenes Geld (z. B. die Jugend), bekommt sie eine eigene Kasse. Wer die Abteilung leitet, sieht dann nur diese Kasse. Optional.": "Якщо відділ має власні гроші (напр. молодь), він отримує власну касу. Керівник відділу бачить тоді лише цю касу. Необов’язково.",
  "Häufige Fragen und Rundgang": "Часті запитання та екскурсія",
