  "Haushaltsplan, Jahresabschluss und Auswertungen rechnen je Haushaltsjahr. Es beginnt entweder am 1. Januar oder mit der Saison.": "Бюджет, річне закриття та звіти рахуються за бюджетними роками. Він починається або 1 січня, або з сезоном.",
