  "Hier findest du alles, womit du selbst bestimmst, wer was von dir sieht und wie die App dich erreicht.": "Тут ти знайдеш усе, чим сам(а) визначаєш, хто що про тебе бачить і як застосунок зв’язується з тобою.",
