  "Je Spiel": "За матч",
  "Je Spiel in der Aufstellung": "Для кожного матчу в складі на матч",
  "Je Spiel: die Nummer wird bei jeder Aufstellung neu vergeben. Fest: eine Nummer pro Spieler für die ganze Saison.": "За матч: номер призначається заново для кожного складу. Фіксований: один номер на гравця на весь сезон.",
  "Je Sponsor": "За спонсором",
  "Jede Änderung setzt die Freigabe der Vorlage zurück.": "Кожна зміна скидає схвалення шаблону.",
  "Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.": "Кожна каса має власні рахунки, внески та звіти. Без призначення відділення працює через головну касу. Річне завершення завжди діє для всього клубу.",
  "Jede Leitung sieht nur Daten ihrer Abteilung": "Кожне керівництво бачить лише дані свого відділення",
  "Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.": "Кожна команда встановлює, до якого часу можливі підтвердження й відмови. Зворотний відлік відображається біля події («Строк: ще 2 дні»). Після цього твоя відповідь залишається видимою (замок «Строк минув»), змінити її може лише твій тренерський штаб.",
  "Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt": "Кожна особа підтверджує або відмовляється – тренер бачить, хто ще не відповів",
  "Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.": "Кожен рядок зелений (новий), синій (оновлений), жовтий (дублікат) або червоний (помилка). Рядки, з яких знято вибір, не застосовуються.",
  "Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.": "Кожен гравець зберігає свій номер; він відображається у складі та в складі на матч.",
  "Jeder Spieler der Startelf braucht einen Platz der Formation.": "Кожен гравець стартового складу потребує позиції в розстановці.",
  "Jedes Feld kann nur einer Spalte zugeordnet werden.": "Кожне поле можна зіставити лише з одним стовпцем.",
  "Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.": "Кожен член клубу в «Клуб → Подати витрату» подає витрати з документом (фото) або витрати на проїзд – для проїзду застосунок рахує з кілометрів (30 центів за км). Скарбник бачить витрати в «Каса клубу → Проводка → Витрати з власних коштів», схвалює або відхиляє з обґрунтуванням і відшкодовує: при цьому в касовій книзі з’являється витрата. На кожному кроці ти отримуєш сповіщення. Відшкодовану витрату не можна сторнувати.",
  "Jetzt einrichten": "Налаштувати зараз",
  "Jetzt eintragen": "Внести зараз",
  "Jetzt starten": "Почати зараз",
  "JPG, PNG oder WebP, höchstens 5 MB.": "JPG, PNG або WebP, не більше 5 МБ.",
  "Jugend": "Молодь",
