  "Kassenprüfer": "Касовий ревізор",
  "Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.": "Касові ревізори починають перевірку за рік у «Каса клубу → Звіти → Касова перевірка» – для всього клубу або лише для своєї каси. За бажанням застосунок вибирає випадкові проводки; кожна проводка позначається виконаною або з обґрунтуванням отримує зауваження, документ ти бачиш одразу. До цього додаються вільні примітки. Коли всі вибіркові перевірки виконано, ти подаєш звіт про перевірку зі своїм результатом; після цього його не можна змінити, і він слугує підставою для розвантаження (затвердження звітності). Керівництво каси бачить подані звіти (також як PDF чи CSV). Ревізори не роблять проводок, скарбник не перевіряє.",
