  "Kurzfristige Absagen und dringende Vereinsnews erreichen dich unabhängig von diesen Einstellungen – auch in der Ruhezeit.": "Термінові відмови й нагальні новини клубу доходять до тебе незалежно від цих налаштувань – також у години тиші.",
