  "Kurztext (optional)": "Короткий текст (необов’язково)",
  "Lade Daten als Excel- oder CSV-Datei herunter. Du siehst nur, wofür du Rechte hast; jeder Export wird im Protokoll des Vereins festgehalten.": "Завантаж дані як файл Excel або CSV. Ти бачиш лише те, на що маєш права; кожен експорт фіксується в журналі клубу.",
  "Lade den Kontoauszug als CSV-Datei deiner Bank hoch. Erkannt werden Buchungstag, Betrag, Name und Verwendungszweck. Zugeordnet wird per Mitgliedsnummer oder Name, wenn der Betrag genau zu einer offenen Forderung passt. Du siehst alles vorher.": "Завантаж виписку з рахунку як файл CSV свого банку. Розпізнаються дата проводки, сума, ім’я та призначення платежу. Зіставлення відбувається за номером члена клубу або іменем, якщо сума точно відповідає відкритій вимозі. Ти бачиш усе наперед.",
  "Lade den Spielplan als CSV-Datei aus dem DFBnet (Meisterschaft › Vereinsspielplan bzw. Mannschaftsspielplan › Export). Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung. Ein erneuter Import aktualisiert bestehende Spiele, statt sie doppelt anzulegen.": "Завантаж календар матчів як файл CSV із DFBnet (Чемпіонат › Календар клубу або Календар команди › Експорт). Спершу ти побачиш попередній перегляд – імпорт відбудеться лише після твого підтвердження. Повторний імпорт оновлює наявні матчі замість їх дублювання.",
