  "Mannschaften melden Spielerbedarf oder bieten Spieler an. Abgestellt wird immer durch den Trainer der abgebenden Mannschaft – andere sehen nur, wie viele Spieler verfügbar sind.": "Команди повідомляють про потребу в гравцях або пропонують гравців. Виділяє завжди тренер команди, що віддає – інші бачать лише, скільки гравців доступно.",
