  "Material und Schlüssel mit Anzahl und Lagerort. Ausgabe an Personen erfolgt später in „Anlage & Material“.": "Матеріали й ключі з кількістю та місцем зберігання. Видача особам відбувається пізніше в «Майно й матеріали».",
