  "Mi": "Ср",
  "Mich": "Мене",
  "Minderjährig ohne Elternteil und ohne E-Mail – später zuordnen.": "Неповнолітній без батьків і без електронної пошти – призначити пізніше.",
  "Mindestens 10 Zeichen – am besten ein kurzer Satz.": "Щонайменше 10 символів – найкраще коротке речення.",
  "Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.": "Щонайменше 10 символів. Послідовність слів або речення безпечніше й легше запам’ятати, ніж короткий пароль зі спеціальними символами.",
  "Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.": "Принаймні одна імпортована особа вже має обліковий запис. Імпорт більше не можна скасувати.",
  "Mindestens zwei Buchstaben eingeben.": "Введи щонайменше дві літери.",
  "Mini-Forum": "Міні-форум",
  "Mit Ablaufdatum": "З датою закінчення",
  "Mit App-Zugang": "З доступом до застосунку",
  "Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.": "Після запуску {0} стає поточним сезоном. Каси команд, документи команд і майбутні події переходять до нових команд. Призначення й завдання старого сезону завершуються. Це неможливо скасувати.",
  "Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.": "Стрілками ти зсуваєш дату на один день. Якщо торкнутися самої дати, відкриється календар: свайпай або торкайся стрілок, щоб змінити місяць, торкнись дня для вибору або вибери «Сьогодні». Недозволені дні сірі.",
  "Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.": "За написаннями з DFBnet імпорт календаря матчів правильно зіставляє матчі.",
  "Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.": "За допомогою адреси Clubroof заповнює підтвердження пожертв; часовий пояс визначає строки й час подій.",
  "Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.": "Із двофакторним входом кожен новий вхід додатково потребує коду. Для облікового запису адміністрації ми рекомендуємо його.",
  "Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.": "Із цією адресою електронної пошти вже є обліковий запис. Увійди або скористайся «Забули пароль».",
  "Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.": "За посиланням-запрошенням або кодом запрошення (також скануванням QR-коду) ти вступаєш до свого клубу – клуб після цього запам’ятовується на цьому пристрої. Якщо в тебе вже є обліковий запис, увійди за допомогою електронної пошти й пароля («Показати» робить пароль видимим). Новий клуб ти налаштовуєш за допомогою коду налаштування (формат CR-XXXX-XXXX), який ти отримаєш від Clubroof після надходження оплати; він дійсний один раз.",
  "Mit Face ID oder Fingerabdruck entsperren": "Розблокувати за допомогою Face ID або відбитка пальця",
  "Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.": "З постійним розкладом тренувань події одразу з’являються в календарі, а підтвердження й відмови працюють із першого дня.",
  "Mit Namen": "З іменами",
  "Mit PayPal bezahlen": "Сплатити через PayPal",
  "Mit Rückmeldung zurückgeben": "Повернути з відповіддю",
