  "Mitglieder › Person › Eltern": "Учасники › Особа › Батьки",
  "Mitglieder (CSV)": "Члени клубу (CSV)",
  "Mitglieder importieren": "Імпортувати членів клубу",
  "Mitglieder importiert nur die Mitgliederverwaltung.": "Членів клубу імпортує лише керування членами клубу.",
  "Mitglieder importiert: {0} neu{1}": "Членів клубу імпортовано: нових {0}{1}",
  "Mitglieder melden Zahlungen in ihrem Konto. Du siehst sie in der Kassenverwaltung unter „Zahlungsmeldungen“ und bestätigst mit „Eingegangen“ – dann wird die Einzahlung gebucht – oder „Nicht gefunden“.": "Члени клубу повідомляють про платежі у своєму обліковому записі. Ти бачиш їх у керуванні касою в «Повідомлення про оплату» і підтверджуєш через «Надійшло» – тоді внесок записується – або «Не знайдено».",
  "Mitglieder ohne Geburtsdatum werden bei der Jugend-Regel übersprungen und bleiben ohne Beitragsart; Mitglieder mit laufender Beitragsart werden nie verändert.": "Члени клубу без дати народження пропускаються за правилом для молоді й залишаються без виду внеску; члени клубу з чинним видом внеску ніколи не змінюються.",
  "Mitglieder reichen Auslagen und Fahrtkosten ein, die Kassenführung prüft sie. Lege fest, wie streng das geschieht.": "Учасники подають витрати та проїзд, каса їх перевіряє. Визначте, наскільки суворо.",
  "Mitglieder, Mannschaften, Termine und Kasse als ZIP mit CSV-Dateien": "Члени клубу, команди, події та каса як ZIP з файлами CSV",
  "Mitglieder, Sport, Inhalte, Verein": "Члени клубу, спорт, вміст, клуб",
