  "Nach Beginn eines Termins hakst du ab, wer wirklich da war (vorausgewählt sind die Zusagen). Danach zählt für Trainingsquote und Statistik die Anwesenheit statt der Zusage. Auf Start erinnert dich ein Hinweis an Trainings der letzten Woche.": "Після початку події ти позначаєш, хто справді був (підтвердження вибрані заздалегідь). Після цього для показника відвідуваності тренувань і статистики враховується присутність замість підтвердження. На головній сторінці примітка нагадує про тренування минулого тижня.",
