  "Name, Kontaktdaten, Mannschaftszugehörigkeit, Zu- und Absagen sowie – nur für Berechtigte – Kassendaten. Gründe für Abwesenheiten sind nur für Trainer und Verantwortliche sichtbar.": "Ім’я, контактні дані, належність до команди, підтвердження й відмови, а також – лише для уповноважених – дані каси. Причини відсутності видимі лише тренерам і відповідальним.",
