  "Nein, es gehört der Mannschaft": "Ні, вона належить команді",
  "Nein. In der Ruhezeit (22 bis 7 Uhr) gibt es keine Push-Nachrichten außer bei dringenden Meldungen. Alles andere wartet bis zum Morgen.": "Ні. У години тиші (з 22:00 до 7:00) push-повідомлень немає, окрім термінових. Усе інше чекає до ранку.",
  "Nein. Trage eine Abwesenheit ein (Urlaub, Verletzt, Krank, Sonstiges). Alle betroffenen Termine werden automatisch abgesagt, das Trainerteam sieht es sofort. Löschst du die Abwesenheit, werden die automatischen Absagen zurückgenommen.": "Ні. Внеси відсутність (відпустка, травма, хвороба, інше). Усі задіяні події автоматично скасовуються, тренерський штаб одразу це бачить. Якщо видалити відсутність, автоматичні відмови скасовуються.",
