  "Nur Admins: Verwaltung › Rollen und Rechte › „Neue Rolle“. Du gibst Name, Beschreibung und den Geltungsbereich (Verein, Abteilung, Mannschaft) an und wählst die Rechte in Klartext; mit „Start als Kopie von“ übernimmst du eine vorhandene Rolle. Sensible Rechte tragen ein Schloss. Vereinsweite Rechte (Verein, Vereinskasse, Mitglieder) gibt es nur in vereinsweiten Rollen, und du kannst nur Rechte vergeben, die du selbst hast. Standardrollen sind geschützt – dort gibt es „Kopie anpassen“. Gelöschte Rollen lassen sich wiederherstellen; Personen stellst du beim Löschen auf eine andere Rolle um. In der Übersicht zeigen die Reiter Rollen, Personen und Matrix den Stand; bei einer Person zeigt „Was darf diese Person?“ jedes Recht mit seiner Quelle.": "Лише адміністратори: Адміністрування › Ролі й права › «Нова роль». Ти вказуєш назву, опис і сферу дії (клуб, відділення, команда) та вибираєш права простою мовою; через «Почати як копію» ти беш наявну роль за основу. Чутливі права мають замок. Права на рівні клубу (клуб, каса клубу, члени клубу) існують лише в ролях на рівні клубу, а надавати можна лише права, які маєш сам(а). Стандартні ролі захищені – для них є «Налаштувати копію». Видалені ролі можна відновити; під час видалення осіб ти переводиш на іншу роль. В огляді вкладки «Ролі», «Особи» та «Матриця» показують стан; для особи «Що може ця особа?» показує кожне право з його джерелом.",
