  "So funktioniert die App. Tippe auf eine Frage, um die Antwort zu lesen – oder suche nach einem Stichwort. Fragen zum Verein selbst beantworten dir die Ansprechpartner.": "Ось як працює застосунок. Торкнись запитання, щоб прочитати відповідь – або шукай за ключовим словом. На запитання про сам клуб відповідають контактні особи.",
