  "So wenig wie nötig: Gründe für Absagen und Abwesenheiten sehen nur das Trainerteam und du. Kontaktdaten sehen nur die Personen, die du freigibst. Eltern sehen die Daten ihrer Kinder. Trainingsbeteiligung und Kassenstand sieht die eigene Mannschaft.": "Якомога менше: причини відмов і відсутностей бачать лише тренерський штаб і ти. Контактні дані бачать лише ті особи, яким ти дозволяєш. Батьки бачать дані своїх дітей. Участь у тренуваннях і стан каси бачить власна команда.",
