  "Sportliche Leitung": "Спортивне керівництво",
  "Sportliche Leitung, Jugendleitung und Vorstand sehen im Reiter „Team“ eine Übersicht über die Abteilungen (Senioren, Frauen, Jugend) – ohne Zugriff in die einzelnen Mannschaften. Oben stehen die Kennzahlen, darunter eine Karte je Mannschaft mit Kader, Trainerteam, Trainingsbeteiligung der letzten 4 Wochen und dem nächsten Spiel. Die Ampel gilt nur für die Trainingsbeteiligung: gut ab 65 %, mittel 50–64 %, niedrig darunter; bei weniger als 3 erfassten Einheiten steht „zu wenig Daten“. Wer auch selbst in einer Mannschaft ist, schaltet oben zwischen „Meine Mannschaft“ und „Übersicht“ um.": "Спортивне керівництво, керівництво молоддю та правління бачать у вкладці «Команда» огляд відділень (дорослі, жінки, молодь) – без доступу до окремих команд. Угорі розміщені показники, нижче – картка для кожної команди зі складом, тренерським штабом, участю в тренуваннях за останні 4 тижні та найближчим матчем. Світлофор стосується лише участі в тренуваннях: добре – від 65 %, середньо – 50–64 %, низько – нижче; якщо зафіксовано менше 3 занять, відображається «замало даних». Хто також сам у команді, перемикається вгорі між «Моя команда» та «Огляд».",
