  "Themen schließt das Moderationsteam.": "Теми закриває команда модерації.",
  "Tipp: Ort in der Karten-App suchen, „Teilen“ wählen und den Link hier einfügen. Ohne Link nutzt „Route“ die eingetragene Adresse.": "Порада: знайди місце в застосунку карт, вибери «Поділитися» й встав посилання сюди. Без посилання «Маршрут» використовує внесену адресу.",
  "Tippe auf der Anmeldeseite auf „Passwort vergessen?“. Du bekommst einen Link per E-Mail, mit dem du ein neues Passwort festlegst. Im Konto kannst du es jederzeit ändern.": "На сторінці входу торкнись «Забули пароль?». Ти отримаєш посилання електронною поштою, за яким встановиш новий пароль. В обліковому записі його можна змінити будь-коли.",
  "Tippe auf die Uhrzeit: Es öffnet sich ein Fenster mit zwei Drehwalzen wie bei einem Wecker – links die Stunde, rechts die Minute (in 5er-Schritten). Wische oder scrolle, bis die richtige Zeit in der Mitte steht, und tippe auf „Übernehmen“. Beim Anlegen eines Termins wählst du Beginn und Ende; die Dauer zeigt die App darunter.": "Торкнись часу: відкриється вікно з двома барабанами, як у будильнику – ліворуч година, праворуч хвилина (кроком 5). Свайпай або прокручуй, доки потрібний час не опиниться посередині, і торкнись «Застосувати». Під час створення події ти вибираєш початок і кінець; тривалість застосунок показує нижче.",
  "Tippe auf einen Spieler, um seine Rückmeldung zu korrigieren.": "Торкнись гравця, щоб виправити його відповідь.",
  "Tippe im Termin bei „Teilnehmer“ auf eine Person und wähle Zusage, Unsicher oder Absage. Das geht auch nach Ablauf der Frist (bis eine Woche nach Beginn).": "У події в «Учасники» торкнись особи й вибери «Підтвердити», «Не впевнений» або «Відмовитися». Це можна зробити й після спливу строку (до тижня після початку).",
  "Tippe in „Mein Konto“ auf „Bezahlen / Zahlung melden“. Du siehst die Bezahlinfos der Mannschaft (IBAN zum Kopieren, PayPal, bar). Nach dem Bezahlen tippst du „Ich habe bezahlt“. Sobald die Kasse den Eingang bestätigt hat, ist dein Konto ausgeglichen.": "У «Мій обліковий запис» торкнись «Сплатити / повідомити про оплату». Ти побачиш платіжну інформацію команди (IBAN для копіювання, PayPal, готівка). Після оплати торкнись «Я заплатив(ла)». Щойно каса підтвердить надходження, твій рахунок буде збалансовано.",
  "Tippe oben rechts auf die Lupe und gib mindestens zwei Buchstaben ein. Du findest Termine, Mitglieder, News und Mannschaften. Personen siehst du nur, wenn du auch sonst ihr Profil sehen darfst (z. B. aus deiner Mannschaft oder deine Kinder).": "Торкнись лупи вгорі праворуч і введи щонайменше дві літери. Ти знайдеш події, членів клубу, новини та команди. Осіб ти бачиш лише тоді, коли й так можеш бачити їхній профіль (напр., зі своєї команди або твої діти).",
