  "Trage ein, wann du nicht verfügbar bist. Betroffene Termine werden automatisch abgesagt, dein Trainerteam sieht es sofort.": "Внеси, коли ти недоступний(а). Задіяні події автоматично скасовуються, твій тренерський штаб одразу це бачить.",
  "Trage ein, wann du oder deine Kinder nicht verfügbar bist. Betroffene Termine werden automatisch abgesagt, dein Trainerteam sieht es sofort.": "Внеси, коли ти або твої діти недоступні. Задіяні події автоматично скасовуються, твій тренерський штаб одразу це бачить.",
  "Trainer": "Тренер",
