  "Trainer entscheiden für ihre Mannschaft, die Verwaltung kann immer freigeben": "Тренери вирішують для своєї команди; адміністрація завжди може схвалити",
  "Trainer sehen Kader und Rückmeldungen und können Termine anlegen. Co-Trainer haben dieselben Rechte.": "Тренери бачать склад і відповіді та можуть створювати події. Асистенти тренера мають ті самі права.",
