  "Trainingsplan, Spielplan oder Termine der Mannschaft mit Datum, Uhrzeit und Platz. Die DFBnet-Datei importierst du weiter unter „Spielplan-Import“.": "План тренувань, календар матчів або події команди з датою, часом і полем. Файл DFBnet, як і раніше, імпортується в «Імпорт календаря матчів».",
