  "Über Clubroof": "Про Clubroof",
  "Über das Schild-Symbol oben rechts oder „Ich → Admin-Verwaltung“ oder „Verein → Meine Vereinsaufgaben → Verwaltung“. Mit „Zur App“ kehrst du zur normalen App zurück. Unten wechselst du zwischen Übersicht, Mitgliedern, Teams, Festen und News.": "Через значок щита вгорі праворуч або «Я → Адміністрування» чи «Клуб → Мої клубні завдання → Адміністрування». Кнопкою «До застосунку» ти повертаєшся до звичайного застосунку. Внизу ти перемикаєшся між оглядом, членами клубу, командами, святами й новинами.",
  "Über den Sponsor": "Про спонсора",
