  "Über Ich → Admin-Verwaltung oder Verein → Meine Vereinsaufgaben → Verwaltung erreichst du Mitglieder, Rollen und Module.": "Через Я → Адміністрування або Клуб → Мої клубні завдання → Адміністрування ти потрапиш до членів клубу, ролей і модулів.",
