  "Üblich": "Звично",
  "Übliche Strafen als Vorlage – abwählen, was ihr nicht wollt. Beträge und weitere Strafen änderst du später.": "Звичні штрафи як шаблон – зніми вибір з того, чого ви не хочете. Суми й інші штрафи ти змінюєш пізніше.",
