  "Umlage": "Розкладка витрат",
  "Umlage buchen": "Записати розкладку витрат",
  "Umlage: {0}": "Розкладка витрат: {0}",
  "Umlage: Gesamtbetrag auf gewählte Personen aufteilen oder festen Betrag je Person fordern. Beiträge: z. B. 5 € monatlich, die App bucht sie allen Spielern zum Fälligkeitstag. Getränke: Preis festlegen und je Person Striche zählen. Alle Betroffenen werden benachrichtigt.": "Розкладка витрат: розподілити загальну суму між вибраними особами або вимагати фіксовану суму з кожної особи. Внески: напр., 5 € щомісяця, застосунок нараховує їх усім гравцям у день строку сплати. Напої: встановити ціну й рахувати позначки на кожну особу. Усі задіяні особи отримують сповіщення.",
  "Umsatzsteuer-ID": "Ідентифікатор ПДВ",
