  "weiter oben in der Datei": "вище у файлі",
  "Weitere Aktionen": "Інші дії",
  "Weitere Anlage hinzufügen": "Додати ще один об’єкт",
  "Weitere Aufgaben": "Інші завдання",
  "Weitere Datei importieren": "Імпортувати ще один файл",
  "Weitere Möglichkeiten": "Інші можливості",
  "Weitere Stufen anzeigen": "Показати інші рівні",
  "Weiteren Termin anlegen": "Створити ще одну подію",
  "Weiteren Termin hinzufügen": "Додати ще одну подію",
  "Weiteres Konto": "Ще один рахунок",
  "Welche Beitragsarten gibt es? Mit Vorschlägen starten und Beträge anpassen.": "Які є види внесків? Почни з пропозицій і скоригуй суми.",
  "Welche Daten habt ihr schon? Die Importe laufen nach der Einrichtung, jeweils mit Vorlage, Spaltenzuordnung und Vorschau. Excel-Dateien mit mehreren Blättern gehen auch – du wählst das Blatt aus.": "Які дані у вас уже є? Імпорти виконуються після налаштування, щоразу з шаблоном, зіставленням стовпців і попереднім переглядом. Файли Excel з кількома аркушами теж підходять – ти вибираєш аркуш.",
  "Welche Daten wir verarbeiten": "Які дані ми обробляємо",
  "Welche Daten wir verarbeiten und warum": "Які дані ми обробляємо й чому",
  "Welche Kasse?": "Яка каса?",
  "Welche Konten und Kassen gibt es?": "Які є рахунки й каси?",
  "Welche Meldungen bekomme ich und wie stelle ich sie ein?": "Які повідомлення я отримую і як їх налаштувати?",
  "Welche Vorlage passt?": "Який шаблон підходить?",
  "Welcher Untergrund?": "Яке покриття?",
  "Welches Mitglied welche Beitragsart zahlt (ab wann, optional mit abweichendem Betrag). Mitglieder werden über Mitgliedsnummer oder Namen erkannt.": "Який член клубу який вид внеску сплачує (з якого часу, за бажанням з іншою сумою). Члени клубу розпізнаються за номером або іменем.",
  "Wenige Themen, die nach Ablauf schließen – für Absprachen, Ideen und Rückmeldungen. Bitte freundlich bleiben; das Moderationsteam blendet Unpassendes aus.": "Кілька тем, що закриваються після завершення – для домовленостей, ідей і відгуків. Будь ласка, залишайся доброзичливим(ою); команда модерації приховує недоречне.",
  "Wenige, moderierte Diskussionsthemen": "Кілька модерованих тем для обговорення",
  "Wenn dein Verein das Sponsoren-Modul nutzt, zeigt ein kleines Wischelement auf Start, im Team-Reiter und im Verein-Reiter bis zu drei Sponsoren, die der Verein als Werbung freigegeben hat. Es ist immer als „Anzeige“ gekennzeichnet und wechselt alle paar Sekunden von selbst; du kannst auch wischen. Ein Tipp öffnet die Seite des Sponsors. Alle Sponsoren findest du unter „Verein → Sponsoren“. Die App wertet nicht aus, wer was ansieht oder antippt. Manche Sponsoren stellt der Verein so ein, dass Jugendspieler sie nicht sehen.": "Якщо твій клуб використовує модуль спонсорів, невеликий елемент для гортання на головній сторінці, у вкладках «Команда» та «Клуб» показує до трьох спонсорів, яких клуб дозволив для реклами. Він завжди позначений як «Реклама» і сам змінюється кожні кілька секунд; ти також можеш гортати. Дотик відкриває сторінку спонсора. Усіх спонсорів ти знайдеш у «Клуб → Спонсори». Застосунок не відстежує, хто що переглядає чи торкається. Деяких спонсорів клуб налаштовує так, щоб юні гравці їх не бачили.",
  "Wenn deine Rückmeldung (oder die deines Kindes) noch fehlt – so lange vor der Frist:": "Якщо твоєї відповіді (або відповіді твоєї дитини) ще немає – за стільки часу до строку:",
  "Wenn du das nicht warst, ignoriere diese E-Mail – dein Passwort bleibt unverändert.": "Якщо це був не ти, проігноруй цей лист – твій пароль залишиться без змін.",
  "Wenn du dich nicht angemeldet hast, ändere bitte dein Passwort.": "Якщо ти не входив(ла), змінь свій пароль.",
  "Wenn eine Mannschaft für ein Spiel Spieler braucht, meldet das Trainerteam einen Bedarf. Andere Mannschaften können Spieler abstellen. Du siehst dann den Einsatz im Termin als „Gastspieler“.": "Якщо команді для матчу потрібні гравці, тренерський штаб повідомляє про потребу. Інші команди можуть виділити гравців. Тоді ти бачиш участь у події як «Запрошений гравець».",
  "Wenn eine Zu- oder Absage noch fehlt": "Якщо підтвердження чи відмови ще немає",
  "Wenn eingeschaltet, brauchen alle mit Verwaltungsrechten (Vorstand, Admins, Jugendleitung …) die 2-Faktor-Anmeldung, bevor sie Mitgliederdaten bearbeiten können.": "Якщо увімкнено, усі з правами адміністрування (правління, адміністратори, керівництво молоддю …) потребують двофакторного входу, перш ніж зможуть редагувати дані членів клубу.",
  "Wer": "Хто",
  "Wer Beiträge und Zuschüsse nach der Saison abrechnet, plant oft lieber in Saisons. Für die Steuererklärung zählt dagegen meist das Kalenderjahr.": "Клуби, що розраховують внески та субсидії за сезонами, часто планують сезонами. Для податкової декларації ж зазвичай діє календарний рік.",
