  "Wer darf die Kasse einsehen?": "Хто може переглядати касу?",
  "Wer deine Daten sieht": "Хто бачить твої дані",
  "Wer die Vereinskasse einsehen darf, bestimmt die Vereinsadministration.": "Хто може переглядати касу клубу, визначає адміністрація клубу.",
