  "Wer sieht, wie viele zu- und abgesagt haben?": "Хто бачить, скільки підтвердили й відмовилися?",
  "Wer soll von Anfang an dabei sein? Jede Person bekommt ihre Rolle und eine Einladung per E-Mail, sobald der Verein eingerichtet ist.": "Хто має бути з самого початку? Кожна особа отримає свою роль і запрошення електронною поштою, щойно клуб буде налаштовано.",
  "Wer spielt in der Mannschaft?": "Хто грає в команді?",
