  "Wer tritt bei?": "Хто вступає?",
  "Wer über einen Einladungslink oder QR-Code beitreten will, stellt eine Anfrage. Jemand muss sie freigeben.": "Хто приєднується за посиланням-запрошенням або QR-кодом, надсилає заявку. Хтось має її схвалити.",
  "Wer übernimmt?": "Хто бере на себе?",
  "Wer vertritt dich?": "Хто вас заступає?",
  "Wer zahlt welchen Beitrag?": "Хто який внесок сплачує?",
  "Wer zugesagt hat oder als Helfer eingetragen ist, erfährt von geänderter Zeit oder geändertem Ort.": "Хто підтвердив або записаний помічником, дізнається про змінений час чи місце.",
  "Werbung an": "Реклама ввімк.",
  "Werbung in der App": "Реклама в застосунку",
  "Werbung je Sponsor als Wischelement mit Kennzeichnung, Seite „Unsere Sponsoren“": "Реклама для кожного спонсора як елемент для гортання з позначкою, сторінка «Наші спонсори»",
  "Werbung läuft für {0} von {1} Sponsoren. Die App zeigt bis zu {2} davon zufällig.": "Реклама діє для {0} з {1} спонсорів. Застосунок показує до {2} з них випадково.",
