  "Zuschüsse": "Дотації",
  "Zuschüsse: Unter „Vereinskasse → Buchung → Zuschüsse“ legst du Förderungen mit Geber, Betrag und Frist für den Verwendungsnachweis an und führst sie von „Geplant“ über „Beantragt“ und „Bewilligt“ bis zum Eingang (Buchung als Einnahme); überfällige Nachweise sind rot. Sponsoren: Beim Buchen einer Einnahme wählst du den Sponsor; unter „Sponsoren“ siehst du die Einnahmen je Sponsor und Jahr. Mannschaftszuschuss: Ausgabe der Vereinskasse und Einnahme der Mannschaftskasse in einem Schritt. Inventar: Unter „Planung → Inventar“ erfasst du Anschaffungen mit Wert und Standort; Gegenstände werden mit Grund ausgesondert, nicht gelöscht.": "Дотації: у «Каса клубу → Проводка → Дотації» ти створюєш фінансування з донором, сумою та строком для звіту про використання коштів і ведеш його від «Заплановано» через «Подано» та «Схвалено» до надходження (проводка як надходження); прострочені звіти червоні. Спонсори: під час запису надходження ти вибираєш спонсора; у «Спонсори» ти бачиш надходження за спонсором і роком. Дотація команді: витрата каси клубу й надходження каси команди за один крок. Інвентар: у «Планування → Інвентар» ти фіксуєш придбання із вартістю й розташуванням; предмети списуються з причиною, а не видаляються.",
  "Zustand / Hinweis (optional)": "Стан / примітка (необов’язково)",
  "Zuwendungsbestätigungen haben gesetzliche Pflichtangaben und Formulierungen. Lass die Vorlage von deiner Steuerberatung oder deinem Verband prüfen, bevor du sie freigibst. Die App ersetzt keine Steuerberatung.": "Підтвердження пожертв мають обов’язкові законодавчі відомості та формулювання. Дай перевірити шаблон своєму податковому консультанту або федерації, перш ніж відкривати його. Застосунок не замінює податкову консультацію.",
  "Zuwendungsbestätigungen noch nicht freigegeben": "Підтвердження пожертв ще не відкрито",
